<main class="section"><div class="section-head"><div><span class="eyebrow">Kategorie-Konfiguration</span><h1><?=App\Core\View::e($category['name'])?></h1></div><a class="btn" href="/admin/kategorien">Kategorien</a></div><section class="card admin-form"><h2>Workflow- und Anforderungskonfiguration</h2><p class="muted">Hier werden Startkontrolle, Nachweise, Versand, Workflow, Endworkflow, technische Anforderungen, Aufgaben- und Fotoanforderungen der Kategorie als wiederverwendbarer Default hinterlegt. Angebote können diese Werte überschreiben.</p><form method="post" action="/admin/kategorien/<?=$category['id']?>/konfiguration" class="form-grid"><?=App\Core\Csrf::field()?><label class="full">Konfiguration (JSON)<textarea name="config_json" rows="14"><?=App\Core\View::e(json_encode(json_decode($category['config_json']?:'{}',true),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES))?></textarea></label><button class="btn primary full">Konfiguration speichern</button></form></section><section class="card admin-form"><h2>Zusätzliches Feld anlegen</h2><form method="post" action="/admin/kategorien/<?=$category['id']?>/felder" class="form-grid"><?=App\Core\Csrf::field()?><label>Feldschlüssel<input name="field_key" placeholder="z. B. groesse" required></label><label>Bezeichnung<input name="label" required></label><label>Typ<select name="field_type"><option value="text">Text</option><option value="number">Zahl</option><option value="select">Auswahl</option><option value="multiselect">Mehrfachauswahl</option><option value="boolean">Ja/Nein</option><option value="date">Datum</option></select></label><label>Sortierung<input name="sort_order" type="number" value="0"></label><label class="full">Auswahloptionen (eine je Zeile)<textarea name="options" rows="4"></textarea></label><label class="check full"><input type="checkbox" name="is_required" value="1"><span>Pflichtfeld</span></label><button class="btn primary full">Feld anlegen</button></form></section><section><h2>Felder</h2><div class="worklist"><?php foreach($fields as $field):?><div class="card admin-form"><form method="post" action="/admin/kategorien/<?=$category['id']?>/felder/<?=$field['id']?>" class="form-grid"><?=App\Core\Csrf::field()?><div class="full"><strong><?=App\Core\View::e($field['field_key'])?></strong></div><label>Bezeichnung<input name="label" value="<?=App\Core\View::e($field['label'])?>" required></label><label>Typ<select name="field_type"><?php foreach(['text'=>'Text','number'=>'Zahl','select'=>'Auswahl','multiselect'=>'Mehrfachauswahl','boolean'=>'Ja/Nein','date'=>'Datum'] as $v=>$l):?><option value="<?=$v?>" <?=$field['field_type']===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select></label><label>Sortierung<input name="sort_order" type="number" value="<?=$field['sort_order']?>"></label><label class="check"><input type="checkbox" name="is_required" value="1" <?=$field['is_required']?'checked':''?>><span>Pflicht</span></label><label class="check"><input type="checkbox" name="is_active" value="1" <?=$field['is_active']?'checked':''?>><span>Aktiv</span></label><label class="full">Optionen<textarea name="options" rows="3"><?php foreach(json_decode($field['options_json']?:'[]',true)?:[] as $opt):?><?=App\Core\View::e($opt)."
"?><?php endforeach;?></textarea></label><button class="btn primary">Speichern</button></form><form method="post" action="/admin/kategorien/<?=$category['id']?>/felder/<?=$field['id']?>/loeschen"><?=App\Core\Csrf::field()?><button class="btn" data-confirm="Feld wirklich löschen?">Feld löschen</button></form></div><?php endforeach;?></div></section></main>